import { NextResponse } from 'next/server';

export async function POST(req: Request) {
  try {
    const inputs = await req.json();
    const baseUrl = process.env.DIFY_API_URL || 'https://api.dify.ai/v1';
    const apiKey = process.env.DIFY_API_KEY;

    if (!apiKey) {
      return NextResponse.json(
        { error: 'DIFY_API_KEYが設定されていません（.env.localを確認してください）' },
        { status: 500 }
      );
    }

    const response = await fetch(`${baseUrl}/completion-messages`, {
      method: 'POST',
      headers: {
        Authorization: `Bearer ${apiKey}`,
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({
        inputs,
        response_mode: 'blocking',
        user: 'dh-staff-demo',
      }),
    });

    if (!response.ok) {
      const errorData = await response.json().catch(() => ({}));

      // Difyがモデル提供元(Google等)のエラーをそのまま返してくることがあるため、中身を見て判定する
      const rawMessage =
        errorData?.message || errorData?.error?.message || JSON.stringify(errorData);

      const isProviderOverloaded =
        rawMessage.includes('UNAVAILABLE') ||
        rawMessage.includes('high demand') ||
        rawMessage.includes('503');

      const friendlyMessage = isProviderOverloaded
        ? 'AIモデルが現在混雑しています。数十秒〜数分待ってから、もう一度お試しください。'
        : `Dify APIエラー (${response.status}): ${rawMessage}`;

      console.error('[Dify API Error]', response.status, errorData);

      return NextResponse.json(
        { error: friendlyMessage, status: response.status, details: errorData },
        { status: response.status }
      );
    }

    const data = await response.json();
    const answerText = data.answer || '';

    const patientSheetMatch = answerText.match(
      /===PATIENT_SHEET_START===([\s\S]*?)===PATIENT_SHEET_END===/
    );
    const talkScriptMatch = answerText.match(
      /===TALK_SCRIPT_START===([\s\S]*?)===TALK_SCRIPT_END===/
    );

    const patientSheet = patientSheetMatch ? patientSheetMatch[1].trim() : answerText;
    const talkScript = talkScriptMatch ? talkScriptMatch[1].trim() : '';

    return NextResponse.json({ success: true, patientSheet, talkScript });
  } catch (error: any) {
    console.error('[Route Error]', error);
    return NextResponse.json(
      { error: 'サーバー内部エラーが発生しました', message: error.message },
      { status: 500 }
    );
  }
}